// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _test(uint256 _val1, uint256 _val2) internal {
        try c.Initialized() {} catch { return; }
        bool reverted = true;
        try c.SetMinSum(_val1) { reverted = false; } catch {}
        assertTrue(reverted);
    }

    function testFuzz_test(uint256 _val1, uint256 _val2) public {
        _test(_val1, _val2);
    }

    receive() external payable {}
}
